344		}
345	
346		var seen []int64
347		for page := 1; page <= 3; page++ {
348			rec := getSBOMs(t, router, fmt.Sprintf("/sboms?artifact=app&page=%d&pageSize=2", page))
349			if rec.Code != http.StatusOK {
350				t.Fatalf("page %d: %d", page, rec.Code)
351			}
352			var got listResponse
353			decodeBody(t, rec, &got)
354			if got.Total != 5 {
355				t.Fatalf("page %d total = %d, want 5", page, got.Total)
356			}
357			if got.Page != page || got.PageSize != 2 {
358				t.Fatalf("echoed paging = %d/%d", got.Page, got.PageSize)
359			}
360			wantItems := 2
361			if page == 3 {
362				wantItems = 1
363			}
364			if len(got.Items) != wantItems {
365				t.Fatalf("page %d items = %d, want %d", page, len(got.Items), wantItems)
366			}
367			for _, item := range got.Items {
