380		// Past the last page: empty items, total unchanged.
381		rec := getSBOMs(t, router, "/sboms?artifact=app&page=4&pageSize=2")
382		var past listResponse
383		decodeBody(t, rec, &past)
384		if len(past.Items) != 0 || past.Total != 5 {
385			t.Fatalf("past-end page = %+v", past)
386		}
387	
388		// Unknown artifact.
389		rec = getSBOMs(t, router, "/sboms?artifact=ghost")
390		var unknown listResponse
