393			t.Fatalf("unknown artifact = %+v", unknown)
394		}
395		if unknown.Page != 1 || unknown.PageSize != 20 {
396			t.Fatalf("defaults = %d/%d, want 1/20", unknown.Page, unknown.PageSize)
397		}
