31	// TestListRequestUsesAtMostFourSelects proves the end-to-end budget through
32	// the real HTTP handler: a page of one and a page of a hundred each issue
33	// exactly four SELECTs, and detail rows never cover anything off the page.
34	func TestListRequestUsesAtMostFourSelects(t *testing.T) {
35		register := func(router *gin.Engine, artifact, version, body string) {
36			t.Helper()
37			if rec := postSBOM(t, router, body); rec.Code != http.StatusCreated {
38				t.Fatalf("register %s@%s: %d %s", artifact, version, rec.Code, rec.Body.String())
