52			if rec.Code != http.StatusOK {
53				t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
54			}
55			counters := counted.Snapshot()
56			if counters.Selects > 4 {
57				t.Fatalf("request issued %d SELECTs, want at most 4", counters.Selects)
58			}
59			if counters.Selects != 4 {
60				t.Fatalf("non-empty page issued %d SELECTs, want exactly 4", counters.Selects)
61			}
62			if counters.RowsByKind["components"] != 3 || counters.RowsByKind["dependencies"] != 3 {
63				t.Fatalf("detail row counts wrong: %+v", counters.RowsByKind)
64			}
