67		t.Run("hundred items", func(t *testing.T) {
68			router, counted := newCountedRouter(t)
69			for i := 0; i < 100; i++ {
70				v := fmt.Sprintf("%02d", i)
71				body := fmt.Sprintf(`{"artifact":"app","version":"%s","components":[
72					{"coordinate":"a","license":"A","dependencies":["b"]},
73					{"coordinate":"b","license":"B","dependencies":[]}
74				]}`, v)
75				register(router, "app", v, body)
76			}
77			// A different artifact whose components share coordinates; never part
78			// of an "app" page.
