1	package api
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"net/http"
7		"testing"
8	
9		"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
10	)
11	
12	// assertErrorOnlyEnvelope proves the failure body carries exactly one
13	// top-level "error" object whose only fields are "code" and "message" — no
14	// partial manifest or page leaks onto the wire.
15	func assertErrorOnlyEnvelope(t *testing.T, body []byte) {
16		t.Helper()
17		var top map[string]json.RawMessage
18		if err := json.Unmarshal(body, &top); err != nil {
19			t.Fatalf("decode %s: %v", body, err)
20		}
21		if len(top) != 1 {
22			t.Fatalf("top-level fields = %v, want only error", keysOf(top))
23		}
24		rawErr, ok := top["error"]
25		if !ok {
26			t.Fatalf("body has no error object: %s", body)
27		}
28		var inner map[string]json.RawMessage
29		if err := json.Unmarshal(rawErr, &inner); err != nil {
30			t.Fatalf("decode error object: %v", err)
31		}
32		if len(inner) != 2 {
33			t.Fatalf("error fields = %v, want code and message only", keysOf(inner))
34		}
35		var code, message string
36		if err := json.Unmarshal(inner["code"], &code); err != nil {
37			t.Fatalf("code is not a string: %v", err)
38		}
39		if err := json.Unmarshal(inner["message"], &message); err != nil {
40			t.Fatalf("message is not a string: %v", err)
41		}
42		if code == "" || message == "" {
43			t.Fatalf("code/message must be non-empty strings: %q/%q", code, message)
44		}
45	}
46	
47	func keysOf(m map[string]json.RawMessage) []string {
48		keys := make([]string, 0, len(m))
49		for k := range m {
50			keys = append(keys, k)
51		}
52		return keys
53	}
54	
55	// TestRegisterDetailWriteFailureReturns503 drives a failing component and a
56	// failing dependency insert through the real HTTP path: both must answer 503
57	// storage_unavailable with an error-only envelope, expose no internals, leave
58	// no trace of the failed registration, and the same request must succeed with
59	// 201 once the (one-shot) fault is consumed — the shared transaction lifecycle
60	// returned the connection and undid the partial write.
61	func TestRegisterDetailWriteFailureReturns503(t *testing.T) {
62		body := `{"artifact":"app","version":"1","components":[
63			{"coordinate":"a","license":"L-a","dependencies":["b"]},
64			{"coordinate":"b","license":"L-b","dependencies":[]}
65		]}`
66	
67		for _, kind := range []string{"components", "dependencies"} {
68			t.Run(kind, func(t *testing.T) {
69				router, counted := newCountedRouter(t)
70	
71				counted.FailNextWrite(kind)
72				rec := postSBOM(t, router, body)
73				if rec.Code != http.StatusServiceUnavailable {
74					t.Fatalf("status = %d, want 503; body %s", rec.Code, rec.Body.String())
75				}
76				assertErrorOnlyEnvelope(t, rec.Body.Bytes())
77				expectError(t, rec, http.StatusServiceUnavailable, "storage_unavailable")
78				for _, leaked := range []string{"INSERT", "SQLITE", "sql:", "goroutine", ".go:", "forced", "/"} {
79					if bytes.Contains(rec.Body.Bytes(), []byte(leaked)) {
80						t.Fatalf("response leaks %q: %s", leaked, rec.Body.String())
81					}
82				}
83	
84				// The failed registration is not queryable: empty page, total 0.
85				listRec := getSBOMs(t, router, "/sboms?artifact=app")
86				var page listResponse
87				decodeBody(t, listRec, &page)
88				if listRec.Code != http.StatusOK || page.Total != 0 || len(page.Items) != 0 {
89					t.Fatalf("failed register visible: status=%d total=%d items=%d",
90						listRec.Code, page.Total, len(page.Items))
91				}
92	
93				// Recovery: the fault was one-shot; the identical request now
94				// creates the manifest and returns the complete record.
95				okRec := postSBOM(t, router, body)
96				if okRec.Code != http.StatusCreated {
97					t.Fatalf("retry status = %d, want 201; body %s", okRec.Code, okRec.Body.String())
98				}
99				var created model.SBOM
100				decodeBody(t, okRec, &created)
101				if created.ID <= 0 || created.Artifact != "app" || created.Version != "1" {
102					t.Fatalf("retry returned incomplete manifest: %+v", created)
103				}
104				if len(created.Components) != 2 ||
105					len(created.Components[0].Dependencies) != 1 ||
106					created.Components[0].Dependencies[0] != "b" {
107					t.Fatalf("retry manifest details wrong: %+v", created.Components)
108				}
109	
110				listRec = getSBOMs(t, router, "/sboms?artifact=app")
111				decodeBody(t, listRec, &page)
112				if page.Total != 1 || len(page.Items) != 1 {
113					t.Fatalf("after recovery total/items = %d/%d, want 1/1", page.Total, len(page.Items))
114				}
115				assertSBOMEqual(t, page.Items[0], &created)
116			})
117		}
118	}
119	
120	// TestRegisterWriteFailureLeavesExistingManifestsWhole makes sure a failed new
121	// registration next to an existing one neither modifies nor hides the
122	// existing manifest.
123	func TestRegisterWriteFailureLeavesExistingManifestsWhole(t *testing.T) {
124		router, counted := newCountedRouter(t)
125		first := postSBOM(t, router, `{"artifact":"app","version":"1","components":[
126			{"coordinate":"a","license":"ORIGINAL","dependencies":[]}
127		]}`)
128		var original model.SBOM
129		decodeBody(t, first, &original)
130	
131		counted.FailNextWrite("components")
132		expectError(t, postSBOM(t, router, `{"artifact":"app","version":"2","components":[
133			{"coordinate":"a","license":"NEW","dependencies":[]}
134		]}`), http.StatusServiceUnavailable, "storage_unavailable")
135	
136		rec := getSBOMs(t, router, "/sboms?artifact=app")
137		var page listResponse
138		decodeBody(t, rec, &page)
139		if page.Total != 1 || len(page.Items) != 1 {
140			t.Fatalf("total/items = %d/%d, want 1/1", page.Total, len(page.Items))
141		}
142		assertSBOMEqual(t, page.Items[0], &original)
143		if page.Items[0].Components[0].License != "ORIGINAL" {
