39	func twoComponents(aDeps []string) []model.Component {
40		return []model.Component{
41			{Coordinate: "a", License: "L-a", Dependencies: aDeps},
42			{Coordinate: "b", License: "L-b", Dependencies: []string{}},
43		}
44	}
45	
46	// TestListUsesAtMostFourSelects proves the query budget against the real
47	// driver: one manifest or a full hundred both take exactly four SELECTs
48	// (count, page rows, one batched components read, one batched dependencies
49	// read), and the two detail reads never return rows for anything outside the
50	// current page and requested artifact.
51	func TestListUsesAtMostFourSelects(t *testing.T) {
52		ctx := context.Background()
53	
54		t.Run("one manifest", func(t *testing.T) {
55			st, counted := openCountingStore(t)
56			registerManifest(t, st, "app", "1", []model.Component{
57				{Coordinate: "a", License: "A", Dependencies: []string{"b", "c"}},
58				{Coordinate: "b", License: "B", Dependencies: []string{"c"}},
59				{Coordinate: "c", License: "C", Dependencies: []string{}},
60			})
61			counted.Reset()
62	
63			items, total, err := st.List(ctx, "app", 1, 20)
64			if err != nil {
65				t.Fatalf("list: %v", err)
66			}
67			counters := counted.Snapshot()
68			if counters.Selects != 4 {
69				t.Fatalf("non-empty page ran %d SELECTs, want exactly 4", counters.Selects)
70			}
71			if total != 1 || len(items) != 1 {
72				t.Fatalf("total/items = %d/%d, want 1/1", total, len(items))
73			}
74			if counters.RowsByKind["count"] != 1 || counters.RowsByKind["sboms"] != 1 ||
75				counters.RowsByKind["components"] != 3 || counters.RowsByKind["dependencies"] != 3 {
76				t.Fatalf("unexpected row reads: %+v", counters.RowsByKind)
77			}
78		})
79	
80		t.Run("hundred manifests", func(t *testing.T) {
81			st, counted := openCountingStore(t)
82			const n = 100
83			for i := 0; i < n; i++ {
84				version := string(rune('0'+i/10)) + string(rune('0'+i%10))
85				registerManifest(t, st, "app", version, twoComponents([]string{"b"}))
86			}
87			// Another artifact sharing the same coordinates: its detail rows must
88			// never be read as part of an "app" page.
89			registerManifest(t, st, "other", "1", []model.Component{
90				{Coordinate: "a", License: "SECRET", Dependencies: []string{"b"}},
91				{Coordinate: "b", License: "SECRET", Dependencies: []string{"a"}},
92			})
93			counted.Reset()
94	
95			items, total, err := st.List(ctx, "app", 1, 100)
96			if err != nil {
97				t.Fatalf("list: %v", err)
98			}
99			counters := counted.Snapshot()
100			if counters.Selects != 4 {
101				t.Fatalf("100-item page ran %d SELECTs, want exactly 4", counters.Selects)
102			}
103			if total != n || len(items) != n {
104				t.Fatalf("total/items = %d/%d, want %d/%d", total, len(items), n, n)
105			}
106			if counters.RowsByKind["sboms"] != n ||
107				counters.RowsByKind["components"] != 2*n ||
108				counters.RowsByKind["dependencies"] != n {
109				t.Fatalf("detail reads escaped the page or artifact: %+v", counters.RowsByKind)
110			}
111			for _, item := range items {
112				if item.Artifact != "app" {
113					t.Fatalf("foreign manifest on page: %q", item.Artifact)
114				}
115				for _, c := range item.Components {
116					if c.License == "SECRET" {
117						t.Fatalf("component from another artifact leaked onto the page: %+v", c)
118					}
119				}
120			}
121		})
122	
123		t.Run("middle page", func(t *testing.T) {
124			st, counted := openCountingStore(t)
125			for i := 0; i < 5; i++ {
126				registerManifest(t, st, "app", string(rune('0'+i)), twoComponents([]string{"b"}))
127			}
128			counted.Reset()
129	
130			items, total, err := st.List(ctx, "app", 2, 2)
131			if err != nil {
132				t.Fatalf("list: %v", err)
133			}
134			counters := counted.Snapshot()
135			if counters.Selects != 4 {
136				t.Fatalf("middle page ran %d SELECTs, want 4", counters.Selects)
137			}
138			if total != 5 || len(items) != 2 {
139				t.Fatalf("total/items = %d/%d, want 5/2", total, len(items))
140			}
141			// Only the two manifests on this page may have their details read.
142			if counters.RowsByKind["sboms"] != 2 ||
143				counters.RowsByKind["components"] != 4 ||
144				counters.RowsByKind["dependencies"] != 2 {
145				t.Fatalf("detail reads escaped the current page: %+v", counters.RowsByKind)
146			}
147		})
148	
149		t.Run("empty page skips detail reads", func(t *testing.T) {
150			for _, tc := range []struct {
151				name     string
152				artifact string
153				page     int
154				wantTot  int
155			}{
156				{"unknown artifact", "ghost", 1, 0},
157				{"past last page", "app", 4, 3},
158			} {
159				t.Run(tc.name, func(t *testing.T) {
160					st, counted := openCountingStore(t)
161					for _, v := range []string{"1", "2", "3"} {
162						registerManifest(t, st, "app", v, twoComponents(nil))
163					}
164					counted.Reset()
165	
166					items, total, err := st.List(ctx, tc.artifact, tc.page, 2)
167					if err != nil {
168						t.Fatalf("list: %v", err)
169					}
170					counters := counted.Snapshot()
171					if counters.Selects > 4 {
172						t.Fatalf("SELECT count = %d, want at most 4", counters.Selects)
173					}
174					// Count plus page scan only; IN-list detail queries must not run.
175					if counters.Selects != 2 ||
176						counters.RowsByKind["components"] != 0 ||
177						counters.RowsByKind["dependencies"] != 0 {
178						t.Fatalf("empty page ran %d selects with rows %+v, want 2 selects and no detail rows",
179							counters.Selects, counters.RowsByKind)
180					}
181					if items == nil || len(items) != 0 {
182						t.Fatalf("items = %v, want non-nil empty slice", items)
183					}
184					if total != tc.wantTot {
185						t.Fatalf("total = %d, want %d", total, tc.wantTot)
186					}
187				})
188			}
189		})
190	}
191	
192	// TestListReconstructsManifests verifies ID ordering, empty-array output,
193	// coordinate ordering and that a legal dependency cycle round-trips completely.
194	func TestListReconstructsManifests(t *testing.T) {
195		st, _ := openCountingStore(t)
196		ctx := context.Background()
197	
198		// Empty manifest: no components at all.
199		registerManifest(t, st, "app", "empty", []model.Component{})
200		// Components without dependencies: dependencies must come back as an empty
201		// array, not null.
202		registerManifest(t, st, "app", "plain", []model.Component{
203			{Coordinate: "z", License: "Z", Dependencies: []string{}},
204			{Coordinate: "a", License: "A", Dependencies: []string{}},
205		})
206		// Legal dependency cycle a<->b must round-trip completely.
207		registerManifest(t, st, "app", "cycle", []model.Component{
208			{Coordinate: "a", License: "A", Dependencies: []string{"b"}},
209			{Coordinate: "b", License: "B", Dependencies: []string{"a"}},
210		})
211	
212		items, total, err := st.List(ctx, "app", 1, 20)
213		if err != nil {
214			t.Fatalf("list: %v", err)
215		}
216		if total != 3 || len(items) != 3 {
217			t.Fatalf("total/items = %d/%d", total, len(items))
218		}
219	
220		empty := items[0]
221		if empty.Version != "empty" || empty.Components == nil || len(empty.Components) != 0 {
222			t.Fatalf("empty manifest = %+v, want non-nil empty components", empty)
223		}
224	
225		plain := items[1]
226		if plain.Version != "plain" {
227			t.Fatalf("items not ordered by id: %s", plain.Version)
228		}
229		if plain.Components[0].Coordinate != "a" || plain.Components[1].Coordinate != "z" {
230			t.Fatalf("components not ordered by coordinate: %+v", plain.Components)
231		}
232		for _, c := range plain.Components {
233			if c.Dependencies == nil || len(c.Dependencies) != 0 {
234				t.Fatalf("empty dependencies of %s = %v, want non-nil empty slice", c.Coordinate, c.Dependencies)
235			}
236		}
237	
238		cycle := items[2]
239		deps := map[string][]string{}
240		for _, c := range cycle.Components {
241			deps[c.Coordinate] = c.Dependencies
242		}
243		if got := deps["a"]; len(got) != 1 || got[0] != "b" {
244			t.Fatalf("cycle edge a-> = %v, want [b]", got)
245		}
246		if got := deps["b"]; len(got) != 1 || got[0] != "a" {
247			t.Fatalf("cycle edge b-> = %v, want [a]", got)
248		}
249	}
250	
251	// TestListKeepsSameCoordinatesScopedPerVersion registers multiple versions
252	// (and another artifact) that share component coordinates but differ in
253	// licenses and dependency edges, then asserts every license and dependency
254	// stays with its own manifest.
255	func TestListKeepsSameCoordinatesScopedPerVersion(t *testing.T) {
256		st, _ := openCountingStore(t)
257		ctx := context.Background()
258	
259		registerManifest(t, st, "app", "1", []model.Component{
260			{Coordinate: "lib", License: "Apache-2.0", Dependencies: []string{"util"}},
261			{Coordinate: "util", License: "BSD-3-Clause", Dependencies: []string{}},
262		})
263		registerManifest(t, st, "app", "2", []model.Component{
264			{Coordinate: "lib", License: "GPL-3.0", Dependencies: []string{}},
265			{Coordinate: "util", License: "MIT", Dependencies: []string{"lib"}},
266		})
267		registerManifest(t, st, "app", "3", []model.Component{
268			{Coordinate: "lib", License: "ISC", Dependencies: []string{"util"}},
269			{Coordinate: "util", License: "Unlicense", Dependencies: []string{"lib"}},
270		})
271		registerManifest(t, st, "vendor", "1", []model.Component{
272			{Coordinate: "lib", License: "PROPRIETARY", Dependencies: []string{}},
273			{Coordinate: "util", License: "PROPRIETARY", Dependencies: []string{}},
274		})
275	
276		items, total, err := st.List(ctx, "app", 1, 100)
277		if err != nil {
278			t.Fatalf("list: %v", err)
279		}
280		if total != 3 || len(items) != 3 {
281			t.Fatalf("total/items = %d/%d, want 3/3", total, len(items))
282		}
283	
284		want := []struct {
285			version     string
286			libLicense  string
287			libDeps     []string
288			utilLicense string
289			utilDeps    []string
290		}{
291			{"1", "Apache-2.0", []string{"util"}, "BSD-3-Clause", []string{}},
292			{"2", "GPL-3.0", []string{}, "MIT", []string{"lib"}},
293			{"3", "ISC", []string{"util"}, "Unlicense", []string{"lib"}},
294		}
295		for i, w := range want {
296			got := items[i]
297			if got.Version != w.version {
298				t.Fatalf("item %d version = %q, want %q", i, got.Version, w.version)
299			}
300			byCoord := map[string]model.Component{}
301			for _, c := range got.Components {
302				byCoord[c.Coordinate] = c
303			}
304			lib, util := byCoord["lib"], byCoord["util"]
305			if lib.License != w.libLicense || !sameStrings(lib.Dependencies, w.libDeps) {
306				t.Fatalf("version %s lib = %+v, want license %q deps %v", w.version, lib, w.libLicense, w.libDeps)
307			}
308			if util.License != w.utilLicense || !sameStrings(util.Dependencies, w.utilDeps) {
309				t.Fatalf("version %s util = %+v, want license %q deps %v", w.version, util, w.utilLicense, w.utilDeps)
310			}
311		}
312	}
313	
314	func sameStrings(a, b []string) bool {
315		if len(a) != len(b) {
316			return false
317		}
318		for i := range a {
319			if a[i] != b[i] {
320				return false
321			}
322		}
323		return true
324	}
325	
326	// TestListReadFailuresReturnUnavailable forces a failure at each of the four
327	// read steps. Every failure must surface model.ErrStorageUnavailable with no
328	// partial items.
329	func TestListReadFailuresReturnUnavailable(t *testing.T) {
330		for _, kind := range []string{"count", "sboms", "components", "dependencies"} {
331			t.Run(kind, func(t *testing.T) {
332				st, counted := openCountingStore(t)
333				registerManifest(t, st, "app", "1", twoComponents([]string{"b"}))
334				counted.FailNextRead(kind)
335	
336				items, _, err := st.List(context.Background(), "app", 1, 20)
337				if err == nil {
338					t.Fatalf("expected failure on %s read", kind)
339				}
340				if !errors.Is(err, model.ErrStorageUnavailable) {
341					t.Fatalf("error = %v, want model.ErrStorageUnavailable", err)
342				}
343				if items != nil {
344					t.Fatalf("items = %v, want nil on failed read", items)
345				}
346			})
347		}
348	}
349	
350	// TestListSnapshotStaysConsistentUnderConcurrentWriters registers manifests
351	// while pages are read. Every returned manifest must be complete (never a
352	// half-written registration) and the page must never contradict its total.
353	func TestListSnapshotStaysConsistentUnderConcurrentWriters(t *testing.T) {
354		st, _ := openCountingStore(t)
355		ctx := context.Background()
356		for i := 0; i < 5; i++ {
357			registerManifest(t, st, "app", string(rune('a'+i)), twoComponents([]string{"b"}))
358		}
359	
360		var wg sync.WaitGroup
361		stop := make(chan struct{})
362		wg.Add(1)
363		go func() {
364			defer wg.Done()
365			for i := 0; ; i++ {
366				select {
367				case <-stop:
368					return
369				default:
370				}
371				version := "writer-" +
372					string(rune('a'+i%26)) +
373					string(rune('a'+(i/26)%26)) +
374					string(rune('a'+(i/676)%26))
375				_, _, _ = st.Register(ctx, &model.SBOM{
376					Artifact:   "app",
377					Version:    version,
378					Components: twoComponents([]string{"b"}),
379				})
380			}
381		}()
382	
383		for i := 0; i < 50; i++ {
384			items, total, err := st.List(ctx, "app", 1, 20)
385			if err != nil {
386				t.Fatalf("list during writes: %v", err)
387			}
388			if len(items) > 20 {
389				t.Fatalf("page returned %d items, want at most 20", len(items))
390			}
391			if len(items) > total {
392				t.Fatalf("items %d exceed total %d within one snapshot", len(items), total)
393			}
394			for _, item := range items {
395				if item.Artifact != "app" || len(item.Components) != 2 {
396					t.Fatalf("incomplete or foreign manifest visible: %+v", item)
397				}
398				deps := map[string][]string{}
399				for _, c := range item.Components {
400					deps[c.Coordinate] = c.Dependencies
401				}
402				if len(deps["a"]) != 1 || deps["a"][0] != "b" {
403					t.Fatalf("partially written manifest visible: %+v", item)
404				}
405			}
406		}
407		close(stop)
408		wg.Wait()
409	}
410

